641: class CRPGClass: public CDBRecord
642: {
643: 	OBJECT_BASIC_METHODS(CRPGClass);
644: public:
645: 	ZDATA_(CDBRecord)
646: 	int nPerkTreeID;
647: 	SRPGSkills skills;
648: 	////
649: 	CPtr<CString> pToolTip;
650: 	CPtr<CUITexture> pIcon;
651: 	CPtr<CUITexture> pIconDisabled;
652: 	CPtr<CUIContainer> pPerksPanel;
653: 	ZEND int operator&( CStructureSaver &f ) { f.Add(1,(CDBRecord*)this); f.Add(2,&nPerkTreeID); f.Add(3,&skills); f.Add(4,&pToolTip); f.Add(5,&pIcon); f.Add(6,&pIconDisabled); f.Add(7,&pPerksPanel); return 0; }
654: 	virtual void Import();

